select log_seq, username, permission_name, path, method, request_body, ip, success, error_message, create_time from sys_audit_log
and log_seq = #{logSeq}
and username like concat('%', #{username}, '%')
and permission_name like concat('%', #{permissionName}, '%')
and success = #{success}
and create_time >= #{startTime}
and create_time <= #{endTime}
order by ${orderBy}
limit #{offset}, #{pageSize}

